// Vérifie la signature Meta (X-Hub-Signature-256) puis renvoie le corps JSON.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};

if ($env.META_SKIP_SIGNATURE !== 'true') {
  if (!item.binary || !item.binary.data) {
    throw new Error('Corps brut absent : activer l\'option "Raw Body" du nœud Webhook');
  }
  const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  const expected = 'sha256=' + crypto
    .createHmac('sha256', $env.META_APP_SECRET)
    .update(raw)
    .digest('hex');
  const received = String(headers['x-hub-signature-256'] || '');
  const ok = received.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
  if (!ok) throw new Error('Signature Meta invalide — requête ignorée');
}

const parsed = typeof body === 'string' ? JSON.parse(body) : body;
return [{ json: { object: parsed.object, body: parsed } }];

// Transforme l'enveloppe Meta en une liste d'événements normalisés :
//   kind = 'message' : message privé reçu (Messenger, Instagram, WhatsApp)
//   kind = 'comment' : commentaire sur une publication (Facebook, Instagram)
const { object, body } = $input.first().json;
const out = [];
const iso = (ms) => new Date(Number(ms)).toISOString();

for (const entry of body.entry || []) {
  if (object === 'page' || object === 'instagram') {
    const channel = object === 'page' ? 'facebook' : 'instagram';
    for (const ev of entry.messaging || []) {
      const m = ev.message;
      if (!m || m.is_echo) continue; // ignorer nos propres messages
      out.push({
        kind: 'message',
        channel,
        account_external_id: String(ev.recipient.id),
        external_user_id: String(ev.sender.id),
        display_name: null, // enrichi plus tard via l'API Profil
        external_message_id: m.mid,
        body: m.text || (m.attachments ? '[pièce jointe]' : '[message non textuel]'),
        sent_at: iso(ev.timestamp),
      });
    }

    for (const change of entry.changes || []) {
      const v = change.value || {};
      // Facebook : field = feed, item = comment, verb = add
      if (channel === 'facebook' && change.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
        out.push({
          kind: 'comment',
          channel,
          account_external_id: String(entry.id),
          comment_id: String(v.comment_id),
          post_id: v.post_id ? String(v.post_id) : null,
          from_id: v.from ? String(v.from.id) : null,
          from_name: v.from ? v.from.name : null,
          body: v.message || '',
        });
      }
      // Instagram : field = comments
      if (channel === 'instagram' && change.field === 'comments') {
        out.push({
          kind: 'comment',
          channel,
          account_external_id: String(entry.id),
          comment_id: String(v.id),
          post_id: v.media ? String(v.media.id) : null,
          from_id: v.from ? String(v.from.id) : null,
          from_name: v.from ? v.from.username : null,
          body: v.text || '',
        });
      }
    }
  }

  if (object === 'whatsapp_business_account') {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const names = Object.fromEntries(
        (v.contacts || []).map((c) => [c.wa_id, c.profile && c.profile.name])
      );
      for (const m of v.messages || []) {
        out.push({
          kind: 'message',
          channel: 'whatsapp',
          account_external_id: String(v.metadata.phone_number_id),
          external_user_id: String(m.from),
          display_name: names[m.from] || null,
          external_message_id: m.id,
          body: m.type === 'text' ? m.text.body : `[${m.type} non pris en charge]`,
          sent_at: iso(Number(m.timestamp) * 1000),
        });
      }
      // v.statuses (sent/delivered/read) seront traités en Partie 5.
    }
  }
}

return out.map((json) => ({ json }));

